/**
 * Extract Notion page/database UUID from a link or raw id (mirrors mcp-notion NotionIdParser).
 */

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const HEX32_RE = /^[0-9a-f]{32}$/i;

function toUuid(hex32) {
  const h = hex32.toLowerCase();
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`;
}

function looksLikeNotionUrl(input) {
  return /notion\.(so|site|com)/i.test(input);
}

function looksLikeUrl(input) {
  return /^https?:\/\//i.test(input) || looksLikeNotionUrl(input);
}

function extractIdFromSegment(segment) {
  if (!segment) return null;
  const dash = segment.lastIndexOf('-');
  if (dash >= 0 && dash < segment.length - 1) {
    const candidate = segment.slice(dash + 1).replace(/-/g, '');
    if (HEX32_RE.test(candidate)) return toUuid(candidate);
  }
  const compact = segment.replace(/-/g, '');
  if (compact.length >= 32) {
    const tail = compact.slice(-32);
    if (HEX32_RE.test(tail)) return toUuid(tail);
  }
  if (HEX32_RE.test(compact)) return toUuid(compact);
  return null;
}

function parseFromNotionUrl(url) {
  try {
    const uri = new URL(url.startsWith('http') ? url : `https://${url}`);
    const path = uri.pathname || '';
    const segment = path.slice(path.lastIndexOf('/') + 1);
    return extractIdFromSegment(segment);
  } catch {
    return null;
  }
}

/** @returns {string|null} normalized UUID or null */
function parseNotionPageId(input) {
  if (!input || typeof input !== 'string') return null;
  const trimmed = input.trim();
  if (!trimmed) return null;
  if (UUID_RE.test(trimmed)) return trimmed.toLowerCase();
  const noDashes = trimmed.replace(/-/g, '');
  if (noDashes.length === 32 && HEX32_RE.test(noDashes)) return toUuid(noDashes);
  if (looksLikeNotionUrl(trimmed)) return parseFromNotionUrl(trimmed);
  if (looksLikeUrl(trimmed)) return null;
  const match = noDashes.match(/[0-9a-f]{32}/i);
  return match ? toUuid(match[0]) : null;
}

function isResolvableNotionPageRef(ref) {
  return !!parseNotionPageId(ref);
}


/**
 * Enrich Notion tool arguments from prior search steps (L2 connector only).
 */

function isWriteTool(toolName) {
  const n = (toolName || '').toLowerCase();
  return n.includes('write') || n.includes('create');
}

function isEditTool(toolName) {
  const n = (toolName || '').toLowerCase();
  return n.includes('edit');
}

function isCreateNew(args) {
  if (!args || typeof args !== 'object') return false;
  const flag = args.create_new;
  if (flag === true || flag === 'true' || flag === 1 || flag === '1') return true;
  const mode = String(args.mode || args.action || '').toLowerCase();
  return mode.includes('create') || mode.includes('new');
}

function parseSearchResultLine(line) {
  const trimmed = (line || '').trim();
  if (!trimmed.startsWith('- ')) return null;
  let body = trimmed.slice(2);
  let id = null;
  const idMatch = body.match(/\{([0-9a-f-]{36})\}\s*$/i);
  if (idMatch) {
    id = idMatch[1].toLowerCase();
    body = body.slice(0, idMatch.index).trim();
  }
  const urlMatch = body.match(/^(.+?)\s+\((https?:\/\/[^)]+)\)\s*$/);
  if (urlMatch) {
    return { title: urlMatch[1].trim(), url: urlMatch[2].trim(), id };
  }
  return { title: body.trim(), url: null, id };
}

function extractPagesFromSearchSummary(summary) {
  if (!summary || typeof summary !== 'string') return [];
  return summary
    .split('\n')
    .map(parseSearchResultLine)
    .filter(Boolean);
}

function pickPageFromPages(pages, pageTitleHint) {
  if (!pages.length) return null;
  if (pageTitleHint) {
    const hint = pageTitleHint.toLowerCase().trim();
    const exact = pages.find((p) => p.title.toLowerCase() === hint);
    if (exact) return exact;
    const partial = pages.find(
      (p) =>
        p.title.toLowerCase().includes(hint) || hint.includes(p.title.toLowerCase()),
    );
    if (partial) return partial;
  }
  if (pages.length === 1) return pages[0];
  return null;
}

function pickPageFromPriorSearch(priorResults, pageTitleHint) {
  const results = priorResults || [];
  for (let i = results.length - 1; i >= 0; i--) {
    const row = results[i];
    if (!row?.ok) continue;
    const n = (row.toolName || '').toLowerCase();
    if (!n.includes('search') && !n.includes('read') && !n.includes('fetch')) continue;
    const pages = extractPagesFromSearchSummary(row.summary);
    const picked = pickPageFromPages(pages, pageTitleHint);
    if (picked) return picked;
  }
  return null;
}

function hasResolvablePageTarget(args) {
  if (!args) return false;
  if (args.page_id && isResolvableNotionPageRef(args.page_id)) return true;
  if (args.page_url && isResolvableNotionPageRef(args.page_url)) return true;
  return false;
}

function applyPickedPage(base, picked) {
  if (!picked) return;
  if (picked.id) {
    base.page_id = picked.id;
  } else if (picked.url) {
    const parsed = parseNotionPageId(picked.url);
    if (parsed) base.page_id = parsed;
  }
  if (picked.url) {
    base.page_url = picked.url;
  }
  if (picked.title && !base.page_title) {
    base.page_title = picked.title;
  }
}

function enrichPageTargetArguments(toolName, args, priorResults, toolMatcher) {
  const base = { ...(args || {}) };
  if (!toolMatcher(toolName) || isCreateNew(base)) {
    return base;
  }
  const hint = base.page_title || base.target_page || base.title || null;
  const picked = pickPageFromPriorSearch(priorResults, hint);
  if (hasResolvablePageTarget(base)) {
    if (!base.page_id && base.page_url) {
      const parsed = parseNotionPageId(base.page_url);
      if (parsed) base.page_id = parsed;
    }
    return base;
  }
  applyPickedPage(base, picked);
  return base;
}

function enrichWriteArguments(toolName, args, priorResults) {
  return enrichPageTargetArguments(toolName, args, priorResults, isWriteTool);
}

function enrichEditArguments(toolName, args, priorResults) {
  return enrichPageTargetArguments(toolName, args, priorResults, isEditTool);
}

function enrichNotionToolArguments(toolName, args, priorResults) {
  let out = enrichWriteArguments(toolName, args, priorResults);
  out = enrichEditArguments(toolName, out, priorResults);
  return out;
}


/**
 * Detect failed / empty Notion search for plan branching (onFailure).
 */

/** @param {string} toolName @param {string} summary */
function isFailedNotionSearch(toolName, summary) {
  const n = (toolName || '').toLowerCase();
  if (!n.includes('search')) {
    return false;
  }
  const s = (summary || '').toLowerCase();
  if (s.includes('ничего не найдено') || s.includes('not found') || s.includes('0 страниц')) {
    return true;
  }
  return extractPagesFromSearchSummary(summary).length === 0;
}


// Run internal Notion tool steps via generic chat-tool-step.
const prep = $('Parse Connector Task').first().json;
if (!prep.valid) {
  return [
    {
      json: {
        action: 'continue',
        ok: false,
        error: prep.error,
        stepResult: { ok: false, error: prep.error },
      },
    },
  ];
}

const internalPrior = [];
let lastToolName = null;

for (let i = 0; i < prep.internalSteps.length; i++) {
  const internal = prep.internalSteps[i];
  const enrichedArgs = enrichNotionToolArguments(
    internal.toolName,
    internal.arguments || {},
    [...(prep.priorResults || []), ...internalPrior],
  );
  const toolStep = {
    connectorKey: 'notion',
    toolName: internal.toolName,
    arguments: enrichedArgs,
  };

  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: prep.toolStepUrl,
    json: true,
    body: {
      orgId: prep.orgId,
      workspaceId: prep.workspaceId,
      userId: prep.userId,
      runId: prep.runId,
      step: toolStep,
      stepIndex: i + 1,
      totalSteps: prep.internalSteps.length,
      priorResults: internalPrior,
    },
  });

  lastToolName = internal.toolName;

  if (res.action === 'complete') {
    return [
      {
        json: {
          action: 'complete',
          ok: true,
          toolName: lastToolName,
          callback: res.callback,
          stepResult: res.stepResult,
        },
      },
    ];
  }

  const row = {
    stepIndex: i + 1,
    connectorKey: 'notion',
    toolName: internal.toolName,
    label: internal.label,
    ok: res.stepResult?.ok,
    summary: res.stepResult?.summary,
    error: res.stepResult?.error,
  };
  if (isFailedNotionSearch(internal.toolName, row.summary)) {
    row.ok = false;
    row.error = row.summary || 'Страницы не найдены в Notion';
  }
  internalPrior.push(row);

  if (!row.ok) {
    return [
      {
        json: {
          action: 'continue',
          ok: false,
          toolName: lastToolName,
          summary: row.error || res.stepResult?.error || 'Notion step failed',
          error: row.error || res.stepResult?.error,
          stepResult: row,
          artifacts: buildConnectorArtifacts(internalPrior),
        },
      },
    ];
  }
}

const last = internalPrior[internalPrior.length - 1];
return [
  {
    json: {
      action: 'continue',
      ok: true,
      toolName: lastToolName,
      summary: last?.summary,
      stepResult: last,
      artifacts: buildConnectorArtifacts(internalPrior),
    },
  },
];
